return scope === 'project'
        ? { configPath: join(repoRoot, '.mcp.json'), format: 'json-mcpServers' }
        : { configPath: '<claude mcp add -s user>', format: 'claude-cli' };

return scope === 'project'
        ? { configPath: join(repoRoot, '.cursor', 'mcp.json'), format: 'json-mcpServers' }
        : { configPath: join(home, '.cursor', 'mcp.json'), format: 'json-mcpServers' };

return scope === 'project'
        ? { configPath: join(repoRoot, '.vscode', 'mcp.json'), format: 'json-servers' }
        : null;

return scope === 'project'
        ? { configPath: join(repoRoot, '.codex', 'config.toml'), format: 'toml' }
        : { configPath: join(home, '.codex', 'config.toml'), format: 'toml' };

out.push({
        ide,
        scope,
        configPath: '',
        written: false,
        command: bin,
        args: [],
        note: `${ide} does not support ${scope}-scope MCP config (upstream); skipping.`,
      });

out.push({
          ide,
          scope,
          configPath: target.configPath,
          written: false,
          command: bin,
          args,
          note: 'claude CLI not found on PATH; install Claude Code, or use project-scope `crib mcp install --ide claude`.',
        });

out.push({
        ide,
        scope,
        configPath: '',
        written: false,
        command: '',
        args: [],
        note: `unsupported for ${ide}/${scope}`,
      });

out.push({
          ide,
          scope,
          configPath: target.configPath,
          written: true,
          command: '',
          args: [],
        });

out.push({
          ide,
          scope,
          configPath: target.configPath,
          written: false,
          command: '',
          args: [],
          note: 'claude CLI not found',
        });

out.push({
        ide,
        scope,
        configPath: target.configPath,
        written: false,
        command: '',
        args: [],
      });

out.push({
        ide,
        scope,
        configPath: target.configPath,
        written: updated !== existing,
        command: '',
        args: [],
      });

out.push({
        ide,
        scope,
        configPath: target.configPath,
        written: false,
        command: '',
        args: [],
      });

return {
    async readText() {
      return text;
    },
    treeSitter() {
      throw new Error('not used — Java is hand-rolled, no tree-sitter');
    },
    hash: contentHash,
    idFor: (kind: NodeKind, parts) => idFor({ kind, ...parts } as IdSpec),
  };

return (id: string): string => {
    const n = r.nodes.find((x) => x.id === id);
    // 1.3: `field` nodes carry a qualifiedName too (e.g. AuthController.service) — prefer it so the
    // member-of assertions stay readable; fall back to kind for file/route/explanation nodes.
    return n?.qualifiedName ?? n?.name ?? n?.kind ?? id;
  };
